import { defineSlot } from '../Slot';

/**
 * A row action on a project's invoices table — a per-invoice control rendered in the row's last cell
 * (the Slot is a Fragment, so it is valid inside a <td>). Features add actions here as new *.slot.tsx
 * files; the invoices panel never lists them. First use: the button that marks an invoice paid.
 */
export const InvoiceRow = defineSlot<{ invoiceId: number; projectId: number }>('invoice.row');
=====src/main/frontend/features/invoices/status.slot.tsx=====
import { useQuery } from '@tanstack/react-query';
import { InvoiceDetail } from '../../slots/defs/invoiceDetail';
import { getInvoice } from './api';
import { paymentsKey } from './paymentsApi';

// This invoice's status, WORKED OUT from its payments — one panel filling the invoice.detail region.
// The server derives it (still owing / part paid / paid) from the payments recorded against the
// invoice, so there is no flipping it to paid by hand. It stays in step with the payments the same
// way every other panel does: by sharing the KEY. The query sits UNDER ['invoice-payments', id], so
// the record form's invalidate of that key (prefix match) refetches this status too — no import
// between them and nothing passed down.
function InvoiceStatus({ invoiceId }: { invoiceId: number }) {
  const { data: invoice } = useQuery({
    queryKey: [...paymentsKey(invoiceId), 'invoice'],
    queryFn: () => getInvoice(invoiceId),
  });

  if (!invoice) {
    return null;
  }

  return <p data-testid="invoice-status">{invoice.status}</p>;
}

export const contribution = InvoiceDetail.fill({ order: 5, Component: InvoiceStatus });
=====src/main/frontend/features/invoices/statusFilter.slot.tsx=====
import { AllInvoicesToolbar } from '../../slots/defs/allInvoicesToolbar';
import { useSearchParam, asString } from '../../url/useSearchParam';

// A control over the all-invoices list — one new *.slot.tsx filling the invoices.toolbar region. It
// owns the `invoiceStatus` URL key; the list reads the same key and asks the server for only that
// stage. Nothing is passed between them: they stay in step through the shared search param. The
// empty option clears the key, so the list falls back to showing every stage.
const STAGES = ['DRAFT', 'SENT', 'PAID'] as const;

function InvoiceStatusFilter() {
  const [status, setStatus] = useSearchParam('invoiceStatus', asString);
  return (
    <select
      data-testid="invoice-status-filter"
      value={status}
      onChange={(e) => setStatus(e.target.value)}
    >
      <option value="">All stages</option>
      {STAGES.map((stage) => (
        <option key={stage} value={stage}>
          {stage}
        </option>
      ))}
    </select>
  );
}

export const contribution = AllInvoicesToolbar.fill({ order: 10, Component: InvoiceStatusFilter });

