=====src/main/java/net/officefloor/hq/app/ListAllInvoices.java=====
package net.officefloor.hq.app;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * GET /api/invoices/all?status=&lt;stage&gt; — every invoice across every project, in id order, each
 * carrying the NAME of the project it is for and its lifecycle stage (status). One place listing all
 * invoices, so it injects both repositories and joins the project name on the server. The optional
 * {@code status} narrows the list to a single stage (DRAFT, SENT, PAID); blank means every stage.
 * Wired by officefloor/rest/api/invoices/all.GET.yml.
 */
public class ListAllInvoices {

    public void service(@RequestParam("status") String status,
            InvoiceRepository invoices, ProjectRepository projects,
            ObjectResponse<List<AllInvoiceView>> response) {
        Map<Long, String> names = projects.findAll().stream()
                .collect(Collectors.toMap(Project::getId, Project::getName));
        boolean all = status == null || status.isBlank();
        List<AllInvoiceView> view = invoices.findAll().stream()
                .filter(inv -> all || status.equals(inv.getStatus()))
                .sorted((a, b) -> Long.compare(a.getId(), b.getId()))
                .map(inv -> AllInvoiceView.of(inv, names.getOrDefault(inv.getProjectId(), "")))
                .toList();
        response.send(view);
    }
}
=====src/main/java/net/officefloor/hq/app/AllInvoiceView.java=====
package net.officefloor.hq.app;

import java.math.BigDecimal;

/**
 * What the API exposes for an invoice in the cross-project list: the shape the "all invoices" page
 * renders. The cross-entity join lives here — each invoice carries its project's NAME (not just the
 * id) so the one list can show which project the invoice is for without a second lookup. The amount
 * keeps its {@link BigDecimal} scale so the client formats it to two places.
 */
public record AllInvoiceView(Long id, Long projectId, String projectName, String status,
        BigDecimal amount) {

    public static AllInvoiceView of(Invoice invoice, String projectName) {
        return new AllInvoiceView(invoice.getId(), invoice.getProjectId(), projectName,
                invoice.getStatus(), invoice.getAmount());
    }
}
=====src/main/java/net/officefloor/hq/app/InvoiceRepository.java=====
package net.officefloor.hq.app;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

/** Data access for {@link Invoice}. A Spring bean, injected into the OfficeFloor logic classes. */
public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    /** The invoices of one project, in id order — the shape the project detail page lists. */
    List<Invoice> findByProjectIdOrderByIdAsc(Long projectId);

    /** The invoices of one project, earliest due date first (ties broken by id for a stable order). */
    List<Invoice> findByProjectIdOrderByDueDateAscIdAsc(Long projectId);
}
